6	import { randomUUID } from 'node:crypto';
7	import type { JSONSchemaType } from 'ajv';
8	import type { AsyncContextProcessor, ProcessArgs } from '../pipeline.js';
9	import type { ContextEnvironment } from '../pipeline/environment.js';
10	import { type ConcreteNode, NodeType } from '../graph/types.js';
11	import { SnapshotGenerator } from '../utils/snapshotGenerator.js';
12	import { debugLogger } from '../../utils/debugLogger.js';
13	
14	export interface StateSnapshotAsyncProcessorOptions {
15	  type?: 'accumulate' | 'point-in-time';
16	  systemInstruction?: string;
17	}
18	
19	export const StateSnapshotAsyncProcessorOptionsSchema: JSONSchemaType<StateSnapshotAsyncProcessorOptions> =
20	  {
21	    type: 'object',
22	    properties: {
23	      type: {
24	        type: 'string',
25	        enum: ['accumulate', 'point-in-time'],
26	        nullable: true,
27	      },
28	      systemInstruction: { type: 'string', nullable: true },
29	    },
30	    required: [],
31	  };
32	
33	export function createStateSnapshotAsyncProcessor(
34	  id: string,
35	  env: ContextEnvironment,
36	  options: StateSnapshotAsyncProcessorOptions,
37	): AsyncContextProcessor {
38	  const generator = new SnapshotGenerator(env);
39	
40	  return {
41	    id,
42	    name: 'StateSnapshotAsyncProcessor',
43	    process: async ({ targets, inbox }: ProcessArgs): Promise<void> => {
44	      if (targets.length === 0) return;
45	
46	      try {
47	        let nodesToSummarize = [...targets];
48	        let previousConsumedIds: string[] = [];
49	        const processorType = options.type ?? 'point-in-time';
50	
51	        if (processorType === 'accumulate') {
52	          // Look for the most recent unconsumed accumulate snapshot in the inbox
53	          const proposedSnapshots = inbox.getMessages<{
54	            newText: string;
55	            consumedIds: string[];
56	            type: string;
57	          }>('PROPOSED_SNAPSHOT');
58	          const accumulateSnapshots = proposedSnapshots.filter(
59	            (s) => s.payload.type === 'accumulate',
60	          );
61	
62	          if (accumulateSnapshots.length > 0) {
63	            // Sort to find the most recent
64	            const latest = [...accumulateSnapshots].sort(
65	              (a, b) => b.timestamp - a.timestamp,
66	            )[0];
67	
68	            // Consume the old draft so the inbox doesn't fill up with stale drafts
69	            inbox.consume(latest.id);
70	            // And we must persist its consumption back to the live inbox immediately,
71	            // because we are effectively "taking" it from the shelf to modify.
72	            env.inbox.drainConsumed(new Set([latest.id]));
73	
74	            previousConsumedIds = latest.payload.consumedIds;
75	
76	            const snapshotId = randomUUID();
77	            const previousStateNode: ConcreteNode = {
78	              id: snapshotId,
79	              turnId: snapshotId,
80	              type: NodeType.SNAPSHOT,
81	              timestamp: latest.timestamp,
82	              role: 'user',
83	              payload: { text: latest.payload.newText },
84	            };
85	
86	            nodesToSummarize = [previousStateNode, ...targets];
87	          }
88	        }
89	
90	        const snapshotText = await generator.synthesizeSnapshot(
91	          nodesToSummarize,
92	          options.systemInstruction,
93	        );
94	
95	        const newConsumedIds = [
96	          ...previousConsumedIds,
97	          ...targets.map((t) => t.id),
98	        ];
99	
100	        // In V2, async pipelines communicate their work to the inbox, and the processor picks it up.
101	        env.inbox.publish('PROPOSED_SNAPSHOT', {
102	          newText: snapshotText,
103	          consumedIds: newConsumedIds,
104	          type: processorType,
105	          timestamp: targets[targets.length - 1].timestamp,
106	        });
107	      } catch (e) {
108	        debugLogger.error(
109	          'StateSnapshotAsyncProcessor failed to generate snapshot',
110	          e,
111	        );
112	      }
113	    },
114	  };
115	}
