1	/**
2	 * @license
3	 * Copyright 2026 Google LLC
4	 * SPDX-License-Identifier: Apache-2.0
5	 */
6	
7	import type { Part } from '@google/genai';
8	
9	/**
10	 * Basic Node Interface
11	 * Every element in the Context Graph is a Node.
12	 */
13	
14	export enum NodeType {
15	  USER_PROMPT = 'USER_PROMPT',
16	  SYSTEM_EVENT = 'SYSTEM_EVENT',
17	  AGENT_THOUGHT = 'AGENT_THOUGHT',
18	  TOOL_EXECUTION = 'TOOL_EXECUTION',
19	  MASKED_TOOL = 'MASKED_TOOL',
20	  AGENT_YIELD = 'AGENT_YIELD',
21	  SNAPSHOT = 'SNAPSHOT',
22	  ROLLING_SUMMARY = 'ROLLING_SUMMARY',
23	}
24	
25	export interface Node {
26	  readonly id: string;
27	  readonly type: NodeType;
28	}
29	
30	/**
31	 * Concrete Nodes: The atomic, renderable pieces of data.
32	 * These are the actual "planks" of the Nodes of Theseus.
33	 *
34	 * Each ConcreteNode is now a 1:1 wrapper around a Gemini Part,
35	 * ensuring 100% fidelity during reconstruction.
36	 */
37	export interface BaseConcreteNode extends Node {
38	  readonly type: NodeType;
39	  readonly timestamp: number;
40	  /** The role of the turn this part belongs to */
41	  readonly role: 'user' | 'model';
42	  /** The original, high-fidelity Part object from the API */
43	  readonly payload: Part;
44	
45	  /** The ID of the specific turn in history this node belongs to. Unique per turn. */
46	  readonly turnId: string;
47	
48	  /** If this node replaced a single node 1:1 (e.g., masking), this points to the original */
49	  readonly replacesId?: string;
50	
51	  /** If this node is a synthetic summary of N nodes, this points to the original IDs */
52	  readonly abstractsIds?: readonly string[];
53	}
54	
55	/**
56	 * Trigger Nodes
57	 * Events that wake the agent up and initiate an Episode.
58	 */
59	export interface UserPrompt extends BaseConcreteNode {
60	  readonly type: NodeType.USER_PROMPT;
61	  readonly role: 'user';
62	}
63	
64	export interface SystemEvent extends BaseConcreteNode {
65	  readonly type: NodeType.SYSTEM_EVENT;
66	  readonly name: string;
67	  readonly payload: Part; // System events are usually injected as user text parts
68	}
69	
70	export type EpisodeTrigger = UserPrompt | SystemEvent;
71	
72	/**
73	 * Step Nodes
74	 * The internal autonomous actions taken by the agent during its loop.
75	 */
76	export interface AgentThought extends BaseConcreteNode {
77	  readonly type: NodeType.AGENT_THOUGHT;
78	  readonly role: 'model';
79	}
80	
81	export interface ToolExecution extends BaseConcreteNode {
82	  readonly type: NodeType.TOOL_EXECUTION;
83	}
84	
85	export interface MaskedTool extends BaseConcreteNode {
86	  readonly type: NodeType.MASKED_TOOL;
87	}
88	
89	export type EpisodeStep = AgentThought | ToolExecution | MaskedTool;
90	
91	/**
92	 * Resolution Node
93	 * The final message where the agent yields control back to the user.
94	 */
95	export interface AgentYield extends BaseConcreteNode {
96	  readonly type: NodeType.AGENT_YIELD;
97	  readonly role: 'model';
98	}
99	
100	/**
101	 * Synthetic Leaf Interfaces
102	 * Processors that generate summaries emit explicit synthetic nodes.
103	 */
104	export interface Snapshot extends BaseConcreteNode {
105	  readonly type: NodeType.SNAPSHOT;
106	}
107	
108	export interface RollingSummary extends BaseConcreteNode {
109	  readonly type: NodeType.ROLLING_SUMMARY;
110	}
111	
112	export type SyntheticLeaf = Snapshot | RollingSummary;
113	
114	export type ConcreteNode =
115	  | UserPrompt
116	  | SystemEvent
117	  | AgentThought
118	  | ToolExecution
119	  | MaskedTool
120	  | AgentYield
121	  | Snapshot
122	  | RollingSummary;
123	
124	export function isAgentThought(node: Node): node is AgentThought {
125	  return node.type === NodeType.AGENT_THOUGHT;
126	}
127	
128	export function isAgentYield(node: Node): node is AgentYield {
129	  return node.type === NodeType.AGENT_YIELD;
130	}
131	
132	export function isToolExecution(node: Node): node is ToolExecution {
133	  return node.type === NodeType.TOOL_EXECUTION;
134	}
135	
136	export function isMaskedTool(node: Node): node is MaskedTool {
137	  return node.type === NodeType.MASKED_TOOL;
138	}
139	
140	export function isUserPrompt(node: Node): node is UserPrompt {
141	  return node.type === NodeType.USER_PROMPT;
142	}
143	
144	export function isSystemEvent(node: Node): node is SystemEvent {
145	  return node.type === NodeType.SYSTEM_EVENT;
146	}
147	
148	export function isSnapshot(node: Node): node is Snapshot {
149	  return node.type === NodeType.SNAPSHOT;
150	}
