import type { ConcreteNode } from '../graph/types.js';

/**
 * Options controlling how a node transcript is rendered for an LLM.
 */
export interface FormatNodesOptions {
  /**
   * The maximum number of characters allowed for a single tool (function)
   * response before it is truncated. Defaults to 2000.
   */
  maxToolResponseChars?: number;
}

const DEFAULT_MAX_TOOL_RESPONSE_CHARS = 2000;

/**
 * Truncates an over-long tool response, keeping the head and tail of the
 * content and replacing the removed middle with a marker of how many
 * characters were dropped.
 */
function truncateToolResponse(text: string, maxChars: number): string {
  if (text.length <= maxChars) {
    return text;
  }

  const removed = text.length - maxChars;
  const headChars = Math.ceil(maxChars / 2);
  const tailChars = maxChars - headChars;

  const prefix = text.slice(0, headChars);
  const suffix = tailChars > 0 ? text.slice(text.length - tailChars) : '';

  return `${prefix}... [TRUNCATED ${removed} chars] ...${suffix}`;
}

/**
 * Renders a sequence of context nodes into a compact, human/LLM readable
 * transcript.
 *
 * Each node becomes a single line of the form:
 *   `[Turn N] [ROLE] [TYPE]: content`
 *
 * where N is a 1-based turn counter (nodes sharing a `turnId` belong to the
 * same turn), ROLE is the upper-cased node role (defaulting to `SYSTEM` when a
 * node has no role), and TYPE is the node's structural type.
 *
 * Content is derived from the node payload:
 *   - text payloads use the raw text
 *   - function calls render as `CALL: name({args})`
 *   - function responses render as `[SEMANTIC_WRAPPER (toolName)]: {json}` and
 *     are truncated when they exceed `maxToolResponseChars`.
 */
export function formatNodesForLlm(
  nodes: readonly ConcreteNode[],
  options: FormatNodesOptions = {},
): string {
  const maxToolResponseChars =
    options.maxToolResponseChars ?? DEFAULT_MAX_TOOL_RESPONSE_CHARS;

  const turnNumbers = new Map<string, number>();
  let nextTurnNumber = 1;

  let transcript = '';

  for (const node of nodes) {
    const turnKey = node.turnId ?? node.id;
    let turnNumber = turnNumbers.get(turnKey);
    if (turnNumber === undefined) {
      turnNumber = nextTurnNumber++;
      turnNumbers.set(turnKey, turnNumber);
    }

    const role = node.role ? node.role.toUpperCase() : 'SYSTEM';

    const payload = node.payload;
    let content = '';
    if (payload.text) {
      content = payload.text;
    } else if (payload.functionCall) {
      content = `CALL: ${payload.functionCall.name}(${JSON.stringify(
        payload.functionCall.args ?? {},
      )})`;
    } else if (payload.functionResponse) {
      const toolName = payload.functionResponse.name ?? 'unknown';
      const responseJson = JSON.stringify(
        payload.functionResponse.response ?? {},
      );
      const truncated = truncateToolResponse(
        responseJson,
        maxToolResponseChars,
      );
      content = `[SEMANTIC_WRAPPER (${toolName})]: ${truncated}`;
    }

    transcript += `[Turn ${turnNumber}] [${role}] [${node.type}]: ${content}\n`;
  }

  return transcript;
}
